const enc = (v) => { if (v === null || v === undefined) return { nullValue: null }; if (typeof v === 'string') return { stringValue: v }; if (typeof v === 'boolean') return { booleanValue: v }; if (typeof v === 'number') return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v }; if (Array.isArray(v)) return { arrayValue: { values: v.map(enc) } }; return { mapValue: { fields: Object.fromEntries(Object.entries(v).map(([k, x]) => [k, enc(x)])) } }; };
const raw = String($input.first().json.choices[0].message.content || '');
const source = $('Switch - Route by Intent').first().json;
if (!source.founder_id) {
  throw new Error('No verified user on this request.');
}
let parsed;
try {
  const m = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : raw);
} catch (e) {
  parsed = { content: source.message, linked_person: null, due_date: null, category: 'task' };
}
const category = (parsed.category === 'commitment' || source.intent === 'store_commitment') ? 'commitment' : 'task';
const due = /^\d{4}-\d{2}-\d{2}/.test(parsed.due_date || '') ? parsed.due_date : '';
const doc = {
  uid: source.founder_id,
  content: parsed.content || source.message,
  linked_person: parsed.linked_person || '',
  due_date: due,
  category,
  status: 'open',
  duration_hours: 1,
  priority: 2,
  missed_count: 0,
  created_at: new Date().toISOString()
};
return [{ json: { ...doc, body: { fields: Object.fromEntries(Object.entries(doc).map(([k, x]) => [k, enc(x)])) } } }];

const j = $input.first().json;
let reply;
if (typeof j.reply === 'string' && j.reply) {
  reply = j.reply;
} else if (j.choices && j.choices[0]) {
  reply = j.choices[0].message.content;
} else {
  try {
    const t = $('Format Task Doc').first().json;
    reply = `Got it, saved: "${t.content}"${t.due_date ? ' (due ' + t.due_date + ')' : ''}.`;
  } catch (e) {
    reply = 'Got it, saved.';
  }
}
return [{ json: { reply } }];

const dec = (v) => { if (!v) return null; if ('stringValue' in v) return v.stringValue; if ('integerValue' in v) return Number(v.integerValue); if ('doubleValue' in v) return v.doubleValue; if ('booleanValue' in v) return v.booleanValue; if ('timestampValue' in v) return v.timestampValue; if ('arrayValue' in v) return (v.arrayValue.values || []).map(dec); if ('mapValue' in v) return Object.fromEntries(Object.entries(v.mapValue.fields || {}).map(([k, x]) => [k, dec(x)])); return null; };
const decDoc = (d) => { const o = { _id: String(d.name || '').split('/').pop() }; for (const [k, v] of Object.entries(d.fields || {})) o[k] = dec(v); return o; };
const input = $input.all().map(i => i.json);
const rows = input.map(t => {
  if (t.document && t.document.fields) return { ...decDoc(t.document), id: decDoc(t.document)._id };
  if (t.fields && t.name) { const d = decDoc(t); return { ...d, id: d._id }; }
  if (t.content) return { ...t, id: t.id || t._id || '' };
  return null;
}).filter(Boolean);
return rows.length ? rows.map(r => ({ json: r })) : [{ json: {} }];

