parameters.jsCode:
const ex = $('Extract Intent').first().json;
const rows = $input.all().map(i => i.json).filter(t => t.content);
const tz = ex.timezone || 'Africa/Lagos';
const msg = String(ex.message || '');

if (!rows.length) {
  return [{ json: { ready: false, reply: "You don't have any open tasks to plan yet. Tell me what you need to do and I'll save it." } }];
}

const reschedule = ex.intent === 'reschedule_task';
const stop = new Set(['move','moving','reschedule','delay','postpone','push','shift','later','tomorrow','today','tonight','morning','afternoon','evening','please','could','would','task','with','that','this','from','need','want','next','week','plan','schedule','again','back']);
const words = msg.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 3 && !stop.has(w));
const hit = r => words.filter(w => (String(r.content) + ' ' + String(r.linked_person || '')).toLowerCase().includes(w)).length;

let list = rows;
if (reschedule) {
  const best = rows.map(r => ({ r, s: hit(r) })).sort((a, b) => b.s - a.s)[0];
  if (!best || best.s === 0) {
    return [{ json: { ready: false, reply: "Which task should I move? Tell me a word from its name, like 'client' or 'budget'." } }];
  }
  list = [best.r];
}

const toTask = r => ({
  id: r.id,
  title: r.content,
  kind: r.category || 'task',
  project: r.linked_person || 'Inbox',
  deadline: r.due_date || null,
  duration_minutes: Math.round((Number(r.duration_hours) || 1) * 60),
  priority: Number(r.priority) || 2,
  importance: [0, 2, 3, 5][Number(r.priority) || 2],
  status: 'open',
  scheduled_start: r.scheduled_start || null,
  scheduled_end: r.scheduled_end || null,
  google_event_id: r.google_event_id || null
});

const body = {
  action: reschedule ? 'reschedule' : 'plan',
  apply: true,
  source: 'assistant',
  message: msg,
  founder_id: ex.founder_id,
  userId: ex.founder_id,
  now: $now.setZone(tz).toISO(),
  timezone: tz,
  focus_date: /tomorrow/i.test(msg) ? $now.plus({ days: 1 }).toFormat('yyyy-MM-dd') : $now.toFormat('yyyy-MM-dd'),
  prefs: { work_hours: '09:00-18:00', peak_window: '09:00-11:00', avoid_after: '18:00', estimate_multiplier: 1.5 },
  tasks: list.map(toTask)
};
if (reschedule && body.tasks[0].scheduled_start) {
  body.exclude = [{ start: body.tasks[0].scheduled_start, end: body.tasks[0].scheduled_end }];
}
return [{ json: { ready: true, body } }];

const inJ = $input.first().json;
const plan = $('Build Plan Request').first().json;
if (!plan.ready) return [{ json: { reply: plan.reply || "I couldn't plan that.", updates: [] } }];
const req = plan.body;
const tz = req.timezone || 'Africa/Lagos';
if (inJ.error && !inJ.choices) return [{ json: { reply: "I couldn't reach the planner just now. Please try again in a moment.", updates: [] } }];

let o = {};
if (inJ.choices && inJ.choices[0]) {
  const c = String((inJ.choices[0].message && inJ.choices[0].message.content) || '');
  try { o = JSON.parse(c.slice(c.indexOf('{'), c.lastIndexOf('}') + 1)); } catch (e) { o = {}; }
}
const items = Array.isArray(o.plan) ? o.plan : (Array.isArray(o.schedule) ? o.schedule : []);
const tasks = req.tasks || [];
const byId = Object.fromEntries(tasks.map(t => [String(t.id), t]));

const wh = String((req.prefs && req.prefs.work_hours) || '09:00-18:00').split('-');
const hm = s => { const p = String(s).split(':'); return { hour: Number(p[0]) || 0, minute: Number(p[1]) || 0, second: 0, millisecond: 0 }; };
const startH = hm(wh[0]);
const endH = hm(wh[1] || '18:00');
const mult = Number(req.prefs && req.prefs.estimate_multiplier) || 1;
const now = DateTime.now().setZone(tz);
const firstFree = now.startOf('minute').plus({ minutes: 15 - (now.minute % 15) });

const busy = (req.exclude || [])
  .map(x => ({ s: DateTime.fromISO(String(x.start)).setZone(tz), e: DateTime.fromISO(String(x.end)).setZone(tz) }))
  .filter(x => x.s.isValid && x.e.isValid);
const clash = (s, e) => busy.some(b => s < b.e && e > b.s);
const inHours = (s, e) => s.hasSame(e, 'day') && s >= s.set(startH) && e <= s.set(endH);
const nextFree = mins => {
  let s = firstFree;
  for (let n = 0; n < 3000; n++) {
    const dayStart = s.set(startH);
    const dayEnd = s.set(endH);
    if (s < dayStart) s = dayStart;
    const e = s.plus({ minutes: mins });
    if (e > dayEnd) { s = dayStart.plus({ days: 1 }); continue; }
    if (clash(s, e)) { s = s.plus({ minutes: 15 }); continue; }
    return { s, e };
  }
  return null;
};

const seen = new Set();
const fixed = [];
const pending = [];
for (const i of items) {
  const id = String(i.task_id || i.taskId || i.id || '');
  if (!byId[id] || seen.has(id)) continue;
  seen.add(id);
  const s = DateTime.fromISO(String(i.start || '')).setZone(tz);
  const e = DateTime.fromISO(String(i.end || '')).setZone(tz);
  const cur = byId[id].scheduled_start;
  const same = req.action === 'reschedule' && cur && s.isValid && Math.abs(s.toMillis() - DateTime.fromISO(String(cur)).toMillis()) < 60000;
  if (s.isValid && e.isValid && e > s && s >= now && inHours(s, e) && !clash(s, e) && !same) {
    busy.push({ s, e });
    fixed.push({ id, s, e, reason: i.reason || '' });
  } else {
    pending.push(id);
  }
}
if (req.action === 'reschedule') {
  for (const t of tasks) if (!seen.has(String(t.id))) pending.push(String(t.id));
}
let adjusted = 0;
for (const id of pending) {
  const mins = Math.max(15, Math.round((Number(byId[id].duration_minutes) || 60) * mult));
  const slot = nextFree(mins);
  if (!slot) continue;
  busy.push(slot);
  fixed.push({ id, s: slot.s, e: slot.e, reason: '' });
  adjusted++;
}

if (!fixed.length) return [{ json: { reply: o.summary || "I couldn't find a free time for that. Try a different day.", updates: [] } }];
fixed.sort((a, b) => a.s.toMillis() - b.s.toMillis());

const when = d => d.toFormat('ccc, LLL d') + ', ' + d.toFormat('h:mm a');
const title = id => (byId[id] && byId[id].title) || 'Task';
const chosen = req.action === 'reschedule' ? fixed.slice(0, 1) : fixed;
let reply;
if (req.action === 'reschedule') {
  const f = chosen[0];
  reply = 'Done. I moved "' + title(f.id) + '" to ' + when(f.s) + ' to ' + f.e.toFormat('h:mm a') + '.' + (f.reason ? ' ' + f.reason : '');
} else {
  const lines = chosen.slice(0, 6).map(f => title(f.id) + ': ' + when(f.s) + ' to ' + f.e.toFormat('h:mm a'));
  reply = (o.summary ? o.summary + '\n' : "Here's your plan:\n") + lines.join('\n') + (chosen.length > 6 ? '\n...and ' + (chosen.length - 6) + ' more.' : '');
  if (adjusted) reply += '\n(I moved ' + adjusted + ' slot' + (adjusted > 1 ? 's' : '') + ' that had already passed or clashed.)';
}
const updated_at = new Date().toISOString();
const updates = chosen.map(f => ({ id: f.id, scheduled_start: f.s.toISO(), scheduled_end: f.e.toISO(), updated_at }));
return [{ json: { reply, updates } }];

